def base_convert(s, from_base, to_base):
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    n = int(s, from_base)
    if n == 0:
        return "0"
    out = []
    while n > 0:
        out.append(digits[n % to_base])
        n //= to_base
    return "".join(reversed(out))

